cat > src/claim-office.spec.ts <<'EOF'
import { describe, it } from "vitest";

describe("MHPCO Claim Office", () => {
  // --- Quote: processing fee and simplest case ---
  it.todo("quotes an empty item list as premium 5 G (processing fee only)");

  // --- Quote: price list base premiums (each entry is independent data) ---
  it.todo("quotes a sword (base 100 G) for a newcomer as premium 116 G (100 + 10 first insurance + 5 fee)");
  it.todo("quotes an amulet (base 60 G) for a newcomer as premium 71 G (60 + 6 first insurance + 5 fee)");
  it.todo("quotes a staff (base 80 G) for a newcomer as premium 93 G (80 + 8 first insurance + 5 fee)");
  it.todo("quotes a potion (base 40 G) for a newcomer as premium 49 G (40 + 4 first insurance + 5 fee)");
  it.todo("quotes a rune component (base 25 G) for a newcomer as premium 33 G (25 + 2.5 first insurance + 5 fee, rounded up)");
  it.todo("quotes a moonstone component (base 25 G) for a newcomer as premium 33 G (25 + 2.5 first insurance + 5 fee, rounded up)");
  it.todo("rejects a quote item with an unknown type (e.g. broomstick) by throwing an Error -- chosen contract: thrown Error, surfaced by the CLI as non-zero exit plus stderr");

  // --- Quote: component building block of 3 alike ---
  it.todo("prices 2 runes as base premium 50 G (no block)");
  it.todo("prices 3 runes as base premium 60 G (block applies)");
  it.todo("prices 4 runes as base premium 100 G (no block -- block requires exactly 3)");
  it.todo("prices 7 runes as base premium 175 G (no block at 7)");
  it.todo("prices 2 runes + 1 moonstone as base premium 75 G (no block: different types are not alike)");
  it.todo("prices 3 runes + 3 moonstones as base premium 120 G (two separate blocks, one per type)");

  // --- Quote: item-specific modifiers ---
  it.todo("adds a 50 % curse surcharge to the cursed item's base premium (cursed sword, newcomer -> 165 G)");
  it.todo("adds a 30 % high-enchantment surcharge for enchantment exactly 5 (sword e5, newcomer -> 149 G)");
  it.todo("adds no high-enchantment surcharge for enchantment 4 (sword e4, newcomer -> 116 G)");
  it.todo("applies item modifiers only to the affected item on a multi-item policy (cursed sword + plain amulet, newcomer -> policy base 160 G, curse adds 50 G -> 247 G)");

  // --- Quote: policy-wide modifiers ---
  it.todo("applies a 20 % loyalty discount at exactly 2 years with MHPCO (sword, 2 years -> 96 G)");
  it.todo("applies no loyalty discount below 2 years with MHPCO (sword, 1 year -> 116 G)");
  it.todo("applies a 15 % follow-up discount to each contract after the customer's first (second quote of a sword, newcomer -> 101 G)");

  // --- Quote: rounding in MHPCO's favour ---
  it.todo("rounds a premium of 197.5 G up to 198 G");

  // --- Claim: payout basics ---
  it.todo("pays a standard claim in full minus a 100 G deductible (steel sword e3, damage 500 G -> payout 400 G)");
  it.todo("reports the remaining cap after a claim (sword, cap 2000 G, damage 500 G -> remainingCap 1600 G)");
  it.todo("applies the 100 G deductible once per damaged item (sword 500 G + amulet 300 G -> payout 600 G)");
  it.todo("reimburses damage to an item with enchantment exactly 8 at 50 % before the deductible (steel sword e8, damage 1000 G -> payout 400 G)");
  it.todo("reimburses damage to an item with enchantment 9 at 50 % before the deductible (steel sword e9, damage 1000 G -> payout 400 G)");
  it.todo("fully reimburses dragon-material damage, then the deductible (dragon sword e5, damage 800 G -> payout 700 G)");
  it.todo("lets the 50 % enchantment rule win over dragon material (dragon sword e9, damage 1000 G -> payout 400 G)");
  it.todo("pays a claim on a component with no enchantment or material (rune, damage 200 G -> payout 100 G)");
  it.todo("rounds a payout of 350.5 G down to 350 G");

  // --- Claim: cap ---
  it.todo("caps the payout at twice the insurance sum across successive claims (sword, cap 2000 G; 1500 G -> 1400 G then 1500 G -> 600 G, remainingCap 0)");
  it.todo("bases the cap on the unmodified insurance sum, not the modified premium (cursed sword -> cap 2000 G)");
  it.todo("excludes the block discount from the insurance sum (sword + 3 runes -> insurance sum 1750 G, cap 3500 G)");
  it.todo("sums insurance values across items for the cap (sword + amulet -> insurance sum 1600 G, cap 3200 G)");
  it.todo("treats two damage entries of the same item type as separate damages with their own deductible (two swords insured, two 500 G sword damages -> payout 800 G)");
  it.todo("rejects a claim with more damage entries of a type than the policy covers by throwing an Error (two sword damages, one sword insured)");
  it.todo("rejects a claim whose damage item is not part of the policy by throwing an Error (amulet damaged, only a sword insured)");
  it.todo("rejects a claim with an unknown damage item type by throwing an Error");
  it.todo("rejects a claim with a negative damage amount by throwing an Error (amount -200)");

  // --- CLI ---
  it.todo("CLI reads a scenario from stdin and writes {results:[{premium}]} to stdout");
  it.todo("CLI writes a claim result as {payout, remainingCap}");
  it.todo("CLI exits non-zero with an error description on stderr and no results on stdout for an unknown item type");

  describe("verification", () => {
    it.todo("quote of a cursed staff applies the curse surcharge to the staff base premium (staff 80 G + 40 G curse, newcomer -> 137 G) -- composes the staff price-list entry with the curse surcharge");
    it.todo("cursed sword with enchantment exactly 5 gets both surcharges (newcomer -> 198 G) -- composes the curse and high-enchantment surcharges");
    it.todo("integration: newcomer with a cursed sword (steel, e3) -> premium 165 G -- composes base premium, curse surcharge, first insurance and fee");
    it.todo("integration: long-standing customer's second contract, cursed sword (steel, e7) -> premium 160 G -- composes curse, high enchantment, loyalty, first insurance, follow-up discount and fee");
    it.todo("dragon-material sword with enchantment exactly 8, damage 1000 G -> payout 400 G -- composes the enchantment-8 threshold with the dragon-material clause");
    it.todo("block pricing combined with a main item (sword + 3 runes, newcomer -> premium 188 G) -- composes the block discount with the price list and policy modifiers");
    it.todo("multi-step scenario: quote then claim against that policy via its step index -- composes quote, policy storage and claim");
    it.todo("CLI processes a scenario of several steps in order, returning results of the same length and order -- composes CLI transport with quote and claim");
  });
});
EOF
