// premium = ceil( policyBase + itemSurcharges, then policy-wide modifiers, + 5 )
// item surcharges: curse 0.5*itemBase, high ench 0.3*itemBase
// policy-wide: loyalty -0.2*policyBase, first ins +0.1*policyBase, followup -0.15*policyBase
function prem({base, curse=0, ench=0, loyal=false, followup=false}) {
  let t = base + curse + ench;
  if (loyal) t -= 0.2*base;
  t += 0.1*base;
  if (followup) t -= 0.15*base;
