input.command:
cat > src/claim-office.ts <<'EOF'
export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

function basePremiumOf(item: Item): number {
  const basePremium = BASE_PREMIUMS[item.type];
  if (basePremium === undefined) {
    throw new Error(`MHPCO does not insure items of type "${item.type}"`);
  }
  return basePremium;
}

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    basePremiumOf(item);
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
}

function policyBasePremium(items: Item[]): number {
  let total = 0;
  for (const [type, count] of countByType(items)) {
    total +=
      count === BLOCK_SIZE
        ? BLOCK_BASE_PREMIUM
        : count * basePremiumOf({ type });
  }
  return total;
}

export function quote(customer: Customer, items: Item[]): number {
  const basePremium = policyBasePremium(items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return Math.ceil(basePremium + firstInsuranceSurcharge + PROCESSING_FEE);
}
EOF
