1	import { describe, expect, it } from "vitest";
2	import { execFileSync } from "node:child_process";
3	import { ClaimOffice } from "./claim-office.js";
4	
5	interface CliOutcome {
6	  status: number;
7	  stdout: string;
8	  stderr: string;
9	}
10	
11	function runCli(scenario: unknown): CliOutcome {
12	  try {
13	    const stdout = execFileSync("pnpm", ["exec", "tsx", "src/cli.ts"], {
14	      input: JSON.stringify(scenario),
15	      encoding: "utf8",
16	      stdio: ["pipe", "pipe", "pipe"],
17	    });
18	    return { status: 0, stdout, stderr: "" };
19	  } catch (error) {
20	    const failure = error as { status: number; stdout: string; stderr: string };
21	    return {
22	      status: failure.status,
23	      stdout: failure.stdout ?? "",
24	      stderr: failure.stderr ?? "",
25	    };
26	  }
27	}
28	
29	describe("MHPCO Claim Office", () => {
30	  // --- Quote: processing fee and simplest case ---
31	  it("quotes an empty item list as premium 5 G (processing fee only)", () => {
32	    expect(new ClaimOffice({ yearsWithMHPCO: 0 }).quote([])).toBe(5);
33	  });
34	
