41	  });
42	  it("quotes a staff (base 80 G) for a newcomer as premium 93 G (80 + 8 first insurance + 5 fee)", () => {
43	    expect(new ClaimOffice({ yearsWithMHPCO: 0 }).quote([{ type: "staff" }])).toBe(93);
44	  });
45	  it("quotes a potion (base 40 G) for a newcomer as premium 49 G (40 + 4 first insurance + 5 fee)", () => {
46	    expect(new ClaimOffice({ yearsWithMHPCO: 0 }).quote([{ type: "potion" }])).toBe(49);
47	  });
48	  it("quotes a rune component (base 25 G) for a newcomer as premium 33 G (25 + 2.5 first insurance + 5 fee, rounded up)", () => {
49	    expect(new ClaimOffice({ yearsWithMHPCO: 0 }).quote([{ type: "rune" }])).toBe(33);
50	  });
51	  it("quotes a moonstone component (base 25 G) for a newcomer as premium 33 G (25 + 2.5 first insurance + 5 fee, rounded up)", () => {
