 25	}
 26	
 27	const PROCESSING_FEE = 5;
 28	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
 29	const LOYALTY_DISCOUNT_RATE = 0.2;
 30	const LOYALTY_YEARS = 2;
 31	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
 32	const DEDUCTIBLE_PER_DAMAGE = 100;
 33	const PARTIAL_REIMBURSEMENT_RATE = 0.5;
 34	const PARTIAL_REIMBURSEMENT_LEVEL = 8;
 35	
 36	const BASE_PREMIUMS: Record<string, number> = {
 37	  sword: 100,
 38	  amulet: 60,
 39	  staff: 80,
 40	  potion: 40,
 41	  rune: 25,
 42	  moonstone: 25,
 43	};
 44	
 45	const CURSE_SURCHARGE_RATE = 0.5;
 46	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
 47	const HIGH_ENCHANTMENT_LEVEL = 5;
 48	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
 49	const INSURANCE_VALUES: Record<string, number> = {
 50	  sword: 1000,
 51	  amulet: 600,
 52	  staff: 800,
 53	  potion: 400,
 54	  rune: 250,
 55	  moonstone: 250,
 56	};
 57	
 58	const CAP_MULTIPLE = 2;
 59	const BLOCK_SIZE = 3;
 60	const BLOCK_BASE_PREMIUM = 60;
 61	
 62	function basePremiumOf(item: Item): number {
 63	  const basePremium = BASE_PREMIUMS[item.type];
 64	  if (basePremium === undefined) {
 65	    throw new Error(`MHPCO does not insure items of type "${item.type}"`);
 66	  }
 67	  return basePremium;
 68	}
 69	
 70	function countByType(items: Item[]): Map<string, number> {
 71	  const counts = new Map<string, number>();
 72	  for (const item of items) {
 73	    basePremiumOf(item);
 74	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
 75	  }
 76	  return counts;
 77	}
 78	
 79	function alikeGroupBasePremium(type: string, count: number): number {
 80	  if (COMPONENT_TYPES.has(type) && count === BLOCK_SIZE) {
 81	    return BLOCK_BASE_PREMIUM;
 82	  }
 83	  return count * basePremiumOf({ type });
 84	}
 85	
 86	function policyBasePremium(items: Item[]): number {
 87	  let total = 0;
 88	  for (const [type, count] of countByType(items)) {
 89	    total += alikeGroupBasePremium(type, count);
 90	  }
 91	  return total;
 92	}
 93	
 94	function riskSurchargeRate(item: Item): number {
 95	  let rate = 0;
 96	  if (item.cursed === true) {
 97	    rate += CURSE_SURCHARGE_RATE;
 98	  }
 99	  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL) {
100	    rate += HIGH_ENCHANTMENT_SURCHARGE_RATE;
101	  }
102	  return rate;
103	}
104	
105	function itemRiskSurcharges(items: Item[]): number {
106	  return items.reduce(
107	    (total, item) => total + basePremiumOf(item) * riskSurchargeRate(item),
108	    0,
109	  );
110	}
111	
112	function policyModifierRate(customer: Customer, previousContracts: number): number {
113	  let rate = FIRST_INSURANCE_SURCHARGE_RATE;
114	  if (customer.yearsWithMHPCO >= LOYALTY_YEARS) {
115	    rate -= LOYALTY_DISCOUNT_RATE;
116	  }
117	  if (previousContracts > 0) {
118	    rate -= FOLLOW_UP_DISCOUNT_RATE;
119	  }
120	  return rate;
121	}
122	
123	function premiumFor(
124	  customer: Customer,
125	  items: Item[],
126	  previousContracts: number,
127	): number {
128	  const basePremium = policyBasePremium(items);
129	  return Math.ceil(
130	    basePremium +
131	      itemRiskSurcharges(items) +
132	      basePremium * policyModifierRate(customer, previousContracts) +
133	      PROCESSING_FEE,
134	  );
135	}
136	
137	function insuranceSum(items: Item[]): number {
138	  return items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
139	}
140	
141	function reimbursementFor(damage: Damage, item: Item): number {
142	  const covered =
143	    (item.enchantment ?? 0) >= PARTIAL_REIMBURSEMENT_LEVEL
144	      ? damage.amount * PARTIAL_REIMBURSEMENT_RATE
145	      : damage.amount;
146	  return covered - DEDUCTIBLE_PER_DAMAGE;
147	}
148	
149	interface Policy {
150	  items: Item[];
151	  remainingCap: number;
152	}
153	
154	function matchDamagesToCoveredItems(policy: Policy, damages: Damage[]): Item[] {
155	  const unclaimed = [...policy.items];
156	  return damages.map((damage) => {
157	    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
158	    if (index === -1) {
159	      throw new Error(
160	        `the policy does not cover a damaged item of type "${damage.itemType}"`,
161	      );
162	    }
163	    return unclaimed.splice(index, 1)[0];
164	  });
165	}
166	
167	function requireWellFormedDamages(damages: Damage[]): void {
168	  for (const damage of damages) {
169	    if (damage.amount < 0) {
170	      throw new Error(`a damage amount cannot be negative: ${damage.amount}`);
171	    }
172	  }
173	}
174	
175	function settle(policy: Policy, incident: Incident): ClaimResult {
176	  requireWellFormedDamages(incident.damages);
177	  const damagedItems = matchDamagesToCoveredItems(policy, incident.damages);
178	  const reimbursement = incident.damages.reduce(
179	    (total, damage, index) => total + reimbursementFor(damage, damagedItems[index]),
180	    0,
181	  );
182	  const payout = Math.min(Math.floor(reimbursement), policy.remainingCap);
183	  policy.remainingCap -= payout;
184	  return { payout, remainingCap: policy.remainingCap };
185	}
186	
187	export class ClaimOffice {
188	  private readonly policies: Policy[] = [];
189	
190	  constructor(private readonly customer: Customer) {}
191	
192	  quote(items: Item[]): number {
193	    const premium = premiumFor(this.customer, items, this.policies.length);
194	    this.policies.push({
195	      items,
196	      remainingCap: insuranceSum(items) * CAP_MULTIPLE,
197	    });
198	    return premium;
199	  }
200	
201	  claim(policyIndex: number, incident: Incident): ClaimResult {
202	    return settle(this.policies[policyIndex], incident);
203	  }
204	}

