45	const CURSE_SURCHARGE_RATE = 0.5;
46	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
47	const HIGH_ENCHANTMENT_LEVEL = 5;
48	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
49	const INSURANCE_VALUES: Record<string, number> = {
50	  sword: 1000,
51	  amulet: 600,
52	  staff: 800,
53	  potion: 400,
54	  rune: 250,
55	  moonstone: 250,
56	};
57	
58	const CAP_MULTIPLE = 2;
59	const BLOCK_SIZE = 3;
60	const BLOCK_BASE_PREMIUM = 60;
61	
62	function basePremiumOf(item: Item): number {
63	  const basePremium = BASE_PREMIUMS[item.type];
64	  if (basePremium === undefined) {
65	    throw new Error(`MHPCO does not insure items of type "${item.type}"`);
66	  }
67	  return basePremium;
68	}
69	
70	function requireInsurableItems(items: Item[]): void {
71	  for (const item of items) {
72	    basePremiumOf(item);
73	  }
74	}
75	
76	function countByType(items: Item[]): Map<string, number> {
77	  const counts = new Map<string, number>();
78	  for (const item of items) {
79	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
80	  }
81	  return counts;
82	}
83	
84	function alikeGroupBasePremium(type: string, count: number): number {
85	  if (COMPONENT_TYPES.has(type) && count === BLOCK_SIZE) {
86	    return BLOCK_BASE_PREMIUM;
87	  }
88	  return count * basePremiumOf({ type });
89	}
90	
91	function policyBasePremium(items: Item[]): number {
92	  let total = 0;
93	  for (const [type, count] of countByType(items)) {
94	    total += alikeGroupBasePremium(type, count);
95	  }
96	  return total;
97	}
98	
99	function riskSurchargeRate(item: Item): number {
100	  let rate = 0;
101	  if (item.cursed === true) {
102	    rate += CURSE_SURCHARGE_RATE;
103	  }
104	  if ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL) {
105	    rate += HIGH_ENCHANTMENT_SURCHARGE_RATE;
106	  }
107	  return rate;
108	}
109	
110	function itemRiskSurcharges(items: Item[]): number {
111	  return items.reduce(
112	    (total, item) => total + basePremiumOf(item) * riskSurchargeRate(item),
113	    0,
114	  );
115	}
116	
117	function policyModifierRate(customer: Customer, previousContracts: number): number {
118	  let rate = FIRST_INSURANCE_SURCHARGE_RATE;
119	  if (customer.yearsWithMHPCO >= LOYALTY_YEARS) {
120	    rate -= LOYALTY_DISCOUNT_RATE;
121	  }
122	  if (previousContracts > 0) {
123	    rate -= FOLLOW_UP_DISCOUNT_RATE;
124	  }
125	  return rate;
126	}
127	
128	function premiumFor(
129	  customer: Customer,
130	  items: Item[],
131	  previousContracts: number,
132	): number {
133	  requireInsurableItems(items);
134	  const basePremium = policyBasePremium(items);
135	  return Math.ceil(
136	    basePremium +
137	      itemRiskSurcharges(items) +
138	      basePremium * policyModifierRate(customer, previousContracts) +
139	      PROCESSING_FEE,
140	  );
141	}
142	
143	function insuranceValueOf(item: Item): number {
144	  const insuranceValue = INSURANCE_VALUES[item.type];
145	  if (insuranceValue === undefined) {
146	    throw new Error(`MHPCO does not insure items of type "${item.type}"`);
147	  }
148	  return insuranceValue;
149	}
150	
151	function insuranceSum(items: Item[]): number {
152	  return items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
153	}
154	
155	function reimbursementFor(damage: Damage, item: Item): number {
156	  const covered =
157	    (item.enchantment ?? 0) >= PARTIAL_REIMBURSEMENT_LEVEL
158	      ? damage.amount * PARTIAL_REIMBURSEMENT_RATE
159	      : damage.amount;
160	  return covered - DEDUCTIBLE_PER_DAMAGE;
161	}
162	
163	interface Policy {
164	  items: Item[];
165	  remainingCap: number;
166	}
167	
168	function matchDamagesToCoveredItems(policy: Policy, damages: Damage[]): Item[] {
169	  const unclaimed = [...policy.items];
170	  return damages.map((damage) => {
171	    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
172	    if (index === -1) {
173	      throw new Error(
174	        `the policy does not cover a damaged item of type "${damage.itemType}"`,
175	      );
176	    }
177	    return unclaimed.splice(index, 1)[0];
178	  });
179	}
180	
181	function requireWellFormedDamages(damages: Damage[]): void {
182	  for (const damage of damages) {
183	    if (damage.amount < 0) {
184	      throw new Error(`a damage amount cannot be negative: ${damage.amount}`);
185	    }
186	  }
187	}
188	
189	function settle(policy: Policy, incident: Incident): ClaimResult {
190	  requireWellFormedDamages(incident.damages);
191	  const damagedItems = matchDamagesToCoveredItems(policy, incident.damages);
192	  const reimbursement = incident.damages.reduce(
193	    (total, damage, index) => total + reimbursementFor(damage, damagedItems[index]),
194	    0,
195	  );
196	  const payout = Math.min(Math.floor(reimbursement), policy.remainingCap);
197	  policy.remainingCap -= payout;
198	  return { payout, remainingCap: policy.remainingCap };
199	}
200	
201	export class ClaimOffice {
202	  private readonly policies: Policy[] = [];
203	
204	  constructor(private readonly customer: Customer) {}
205	
206	  quote(items: Item[]): number {
207	    const premium = premiumFor(this.customer, items, this.policies.length);
208	    this.policies.push({
209	      items,
210	      remainingCap: insuranceSum(items) * CAP_MULTIPLE,
211	    });
212	    return premium;
213	  }
214	
215	  claim(policyIndex: number, incident: Incident): ClaimResult {
216	    return settle(this.policies[policyIndex], incident);
217	  }
218	}

